import java.nio.file.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;
public class PatchTowny {public static void main(String[]args)throws Exception{var c=new ClassNode();new ClassReader(Files.readAllBytes(Path.of(args[0]))).accept(c,0);int changed=0;for(var m:c.methods)if(m.name.equals("forceSettings")){for(var n:m.instructions.toArray())if(n instanceof FieldInsnNode f&&f.name.equals("UseAsyncTargetFinding")){var current=n;boolean done=false;while(current!=null){var next=current.getNext();done=current instanceof MethodInsnNode x&&x.name.equals("set");m.instructions.remove(current);if(done)break;current=next;}if(!done)throw new IllegalStateException("Unexpected obsolete config setter");changed++;}}if(changed!=1)throw new IllegalStateException("Expected exactly one obsolete setter");var w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);Files.write(Path.of(args[1]),w.toByteArray());}}
